entries./**\n *\n * Post an item to the front of:
/**
 *
 * 将一个条目发送到队列的前端（队首）。条目按值拷贝入队，而非按引用。
 * 绝不能在中断服务程序（ISR）中调用此函数。有关可在 ISR 中使用的替代函数，
 * 请参阅 xQueueSendFromISR ()。
 *
 * @param xQueue 将要发送条目的目标队列句柄。
 *
 * @param pvItemToQueue 指向要放入队列的条目的指针。队列所能容纳的条目大小在创建队列时
 * 已定义，因此将从 pvItemToQueue 拷贝相应字节数到队列存储区中。
 *
 * @param xTicksToWait 当队列已满时，任务为等待队列出现可用空间而进入阻塞状态的最大时间。
 * 如果此值设为 0 且队列已满，则调用会立即返回。该时间以 tick 周期为单位定义，因此如需
 * 转换为实际时间，应使用常量 portTICK_PERIOD_MS。
 *
 * @return 如果条目发送成功则返回 pdTRUE，否则返回 errQUEUE_FULL。
 *
 * 使用示例：
 * @code{c}
 * struct AMessage
 * {
 *  char ucMessageID;
 *  char ucData[ 20 ];
 * } xMessage;
 *
 * uint32_t ulVar = 10UL;
 *
 * void vATask( void *pvParameters )
 * {
 * QueueHandle_t xQueue1, xQueue2;
 * struct AMessage *pxMessage;
 *
 *  // 创建一个可容纳 10 个 uint32_t 值的队列。
 *  xQueue1 = xQueueCreate( 10, sizeof( uint32_t ) );
 *
 *  // 创建一个可容纳 10 个指向 AMessage 结构体指针的队列。
 *  // 由于这些结构体包含大量数据，应通过指针传递。
 *  xQueue2 = xQueueCreate( 10, sizeof( struct AMessage * ) );
 *
 *  // ...
 *
 *  if( xQueue1 != 0 )
 *  {
 *      // 发送一个 uint32_t。如有必要，等待 10 个 tick 以获取可用空间。
 *      if( xQueueSendToFront( xQueue1, ( void * ) &ulVar, ( TickType_t ) 10 ) != pdPASS )
 *      {
 *          // 即使等待了 10 个 tick，消息仍发送失败。
 *      }
 *  }
 *
 *  if( xQueue2 != 0 )
 *  {
 *      // 发送一个指向 struct AMessage 对象的指针。如果队列已满则不阻塞。
 *      pxMessage = & xMessage;
 *      xQueueSendToFront( xQueue2, ( void * ) &pxMessage, ( TickType_t ) 0 );
 *  }
 *
 *  // ... 其余任务代码。
 * }
 * @endcode
 * \ingroup QueueManagement
 */

