entries./**\n *\n * Receive an item from a queue:
/**
 *
 * 从队列接收一个条目，但不从队列中移除该条目。
 * 条目通过拷贝接收，因此必须提供足够大小的缓冲区。拷贝到缓冲区中的字节数在创建队列时已定义。
 *
 * 成功接收的条目仍保留在队列中，因此下次调用此函数或调用 xQueueReceive() 时会再次返回该条目。
 *
 * 绝不能在中断服务程序（ISR）中使用此宏。有关可在中断服务程序中调用的替代函数，
 * 请参阅 xQueuePeekFromISR()。
 *
 * @param xQueue 要从中接收条目的队列句柄。
 *
 * @param pvBuffer 指向将要拷贝接收条目的缓冲区的指针。
 *
 * @param xTicksToWait 如果调用时队列为空，任务为等待接收条目而进入阻塞状态的最大时间。
 * 该时间以 tick 周期为单位定义，因此如需转换为实际时间，应使用常量 portTICK_PERIOD_MS。
 * 如果 xTicksToWait 为 0 且队列为空，xQueuePeek() 将立即返回。
 *
 * @return 如果成功从队列接收到条目则返回 pdTRUE，否则返回 pdFALSE。
 *
 * 使用示例：
 * @code{c}
 * struct AMessage
 * {
 *  char ucMessageID;
 *  char ucData[ 20 ];
 * } xMessage;
 *
 * QueueHandle_t xQueue;
 *
 * // 用于创建队列并发送值的任务。
 * void vATask( void *pvParameters )
 * {
 * struct AMessage *pxMessage;
 *
 *  // 创建一个可容纳 10 个指向 AMessage 结构体指针的队列。
 *  // 由于这些结构体包含大量数据，应通过指针传递。
 *  xQueue = xQueueCreate( 10, sizeof( struct AMessage * ) );
 *  if( xQueue == 0 )
 *  {
 *      // 创建队列失败。
 *  }
 *
 *  // ...
 *
 *  // 发送一个指向 struct AMessage 对象的指针。如果队列已满则不阻塞。
 *  pxMessage = & xMessage;
 *  xQueueSend( xQueue, ( void * ) &pxMessage, ( TickType_t ) 0 );
 *
 *  // ... 其余任务代码。
 * }
 *
 * // 用于查看队列数据的任务。
 * void vADifferentTask( void *pvParameters )
 * {
 * struct AMessage *pxRxedMessage;
 *
 *  if( xQueue != 0 )
 *  {
 *      // 查看所创建队列上的消息。如果消息不能立即可用，则阻塞 10 个 tick。
 *      if( xQueuePeek( xQueue, &( pxRxedMessage ), ( TickType_t ) 10 ) )
 *      {
 *          // pcRxedMessage 现在指向由 vATask 发送的 struct AMessage 变量，
 *          // 但该条目仍然保留在队列中。
 *      }
 *  }
 *
 *  // ... 其余任务代码。
 * }
 * @endcode
 * \ingroup QueueManagement
 */

/**
 *
 * 从队列接收一个条目。条目通过拷贝接收，因此必须提供足够大小的缓冲区。
 * 拷贝到缓冲区中的字节数在创建队列时已定义。
 *
 * 成功接收的条目会从队列中移除。
 *
 * 绝不能在中断服务程序（ISR）中使用此函数。有关可在 ISR 中使用的替代函数，
 * 请参阅 xQueueReceiveFromISR。
 *
 * @param xQueue 要从中接收条目的队列句柄。
 *
 * @param pvBuffer 指向将要拷贝接收条目的缓冲区的指针。
 *
 * @param xTicksToWait 如果调用时队列为空，任务为等待接收条目而进入阻塞状态的最大时间。
 * 如果 xTicksToWait 为零且队列为空，xQueueReceive() 将立即返回。该时间以 tick 周期为
 * 单位定义，因此如需转换为实际时间，应使用常量 portTICK_PERIOD_MS。
 *
 * @return 如果成功从队列接收到条目则返回 pdTRUE，否则返回 pdFALSE。
 *
 * 使用示例：
 * @code{c}
 * struct AMessage
 * {
 *  char ucMessageID;
 *  char ucData[ 20 ];
 * } xMessage;
 *
 * QueueHandle_t xQueue;
 *
 * // 用于创建队列并发送值的任务。
 * void vATask( void *pvParameters )
 * {
 * struct AMessage *pxMessage;
 *
 *  // 创建一个可容纳 10 个指向 AMessage 结构体指针的队列。
 *  // 由于这些结构体包含大量数据，应通过指针传递。
 *  xQueue = xQueueCreate( 10, sizeof( struct AMessage * ) );
 *  if( xQueue == 0 )
 *  {
 *      // 创建队列失败。
 *  }
 *
 *  // ...
 *
 *  // 发送一个指向 struct AMessage 对象的指针。如果队列已满则不阻塞。
 *  pxMessage = & xMessage;
 *  xQueueSend( xQueue, ( void * ) &pxMessage, ( TickType_t ) 0 );
 *
 *  // ... 其余任务代码。
 * }
 *
 * // 用于从队列接收数据的任务。
 * void vADifferentTask( void *pvParameters )
 * {
 * struct AMessage *pxRxedMessage;
 *
 *  if( xQueue != 0 )
 *  {
 *      // 接收所创建队列上的消息。如果消息不能立即可用，则阻塞 10 个 tick。
 *      if( xQueueReceive( xQueue, &( pxRxedMessage ), ( TickType_t ) 10 ) )
 *      {
 *          // pcRxedMessage 现在指向由 vATask 发送的 struct AMessage 变量。
 *      }
 *  }
 *
 *  // ... 其余任务代码。
 * }
 * @endcode
 * \ingroup QueueManagement
 */

/**
 *
 * 从队列接收一个条目。在中断服务程序（ISR）中使用此函数是安全的。
 *
 * @param xQueue 要从中接收条目的队列句柄。
 *
 * @param pvBuffer 指向将要拷贝接收条目的缓冲区的指针。
 *
 * @param pxHigherPriorityTaskWoken 可能有任务正阻塞等待队列出现可用空间。
 * 如果 xQueueReceiveFromISR 使此类任务解除阻塞，则 *pxTaskWoken 将被设置为 pdTRUE，
 * 否则 *pxTaskWoken 保持不变。
 *
 * @return 如果成功从队列接收到条目则返回 pdTRUE，否则返回 pdFALSE。
 *
 * 使用示例：
 * @code{c}
 *
 * QueueHandle_t xQueue;
 *
 * // 用于创建队列并发送若干值的函数。
 * void vAFunction( void *pvParameters )
 * {
 * char cValueToPost;
 * const TickType_t xTicksToWait = ( TickType_t )0xff;
 *
 *  // 创建一个可容纳 10 个字符的队列。
 *  xQueue = xQueueCreate( 10, sizeof( char ) );
 *  if( xQueue == 0 )
 *  {
 *      // 创建队列失败。
 *  }
 *
 *  // ...
 *
 *  // 发送一些将在 ISR 中使用的字符。如果队列已满，
 *  // 则此任务将阻塞 xTicksToWait 个 tick。
 *  cValueToPost = 'a';
 *  xQueueSend( xQueue, ( void * ) &cValueToPost, xTicksToWait );
 *  cValueToPost = 'b';
 *  xQueueSend( xQueue, ( void * ) &cValueToPost, xTicksToWait );
 *
 *  // ... 继续发送字符 ... 当队列变满时，
 *  // 此任务可能会阻塞。
 *
 *  cValueToPost = 'c';
 *  xQueueSend( xQueue, ( void * ) &cValueToPost, xTicksToWait );
 * }
 *
 * // 输出从队列中接收到的所有字符的 ISR。
 * void vISR_Routine( void )
 * {
 * BaseType_t xTaskWokenByReceive = pdFALSE;
 * char cRxedChar;
 *
 *  while( xQueueReceiveFromISR( xQueue, ( void * ) &cRxedChar, &xTaskWokenByReceive) )
 *  {
 *      // 已接收到一个字符。立即输出该字符。
 *      vOutputCharacter( cRxedChar );
 *
 *      // 如果从队列中移除该字符唤醒了正在向队列发送数据的任务，
 *      // 则 xTaskWokenByReceive 将已被设置为 pdTRUE。
 *      // 无论此循环迭代多少次，都只会唤醒一个任务。
 *  }
 *
 *  if( xTaskWokenByReceive != ( char ) pdFALSE;
 *  {
 *      taskYIELD ();
 *  }
 * }
 * @endcode
 * \ingroup QueueManagement
 */

