 * 注意：此函数仅用于调试用途，因为使用该函数会导致调度器在较长时间内保持挂起状态。
 *
 * @param pxTaskStatusArray 指向 TaskStatus_t 结构体数组的指针。该数组必须为
 * 受 RTOS 控制的每个任务至少包含一个 TaskStatus_t 结构体。受 RTOS 控制的
 * 任务数量可以使用 uxTaskGetNumberOfTasks() API 函数确定。
 *
 * @param uxArraySize pxTaskStatusArray 参数所指向数组的大小。该大小以数组中的
 * 索引数量（即数组中所含 TaskStatus_t 结构体的数量）指定，而不是以数组的字节数
 * 指定。
 *
 * @param pulTotalRunTime 如果在 FreeRTOSConfig.h 中将
 * configGENERATE_RUN_TIME_STATS 设置为 1，则 uxTaskGetSystemState() 会将
 * *pulTotalRunTime 设置为自目标启动以来的总运行时间（由运行时间统计时钟定义，
 * 参见 https://www.FreeRTOS.org/rtos-run-time-stats.html）。可将
 * pulTotalRunTime 设置为 NULL 以省略总运行时间信息。
 *
 * @return 由 uxTaskGetSystemState() 填充的 TaskStatus_t 结构体数量。该值
 * 应等于 uxTaskGetNumberOfTasks() API 函数返回的数量，但如果 uxArraySize
 * 参数传入的值过小，则将返回零。
 *
 * 使用示例：
 * @code{c}
 *  // 此示例演示如何根据 uxTaskGetSystemState() 提供的原始数据
 *  // 生成人类可读的运行时间统计信息表。
 *  // 人类可读的表格将写入 pcWriteBuffer
 *  void vTaskGetRunTimeStats( char *pcWriteBuffer )
 *  {
 *  TaskStatus_t *pxTaskStatusArray;
 *  volatile UBaseType_t uxArraySize, x;
 *  configRUN_TIME_COUNTER_TYPE ulTotalRunTime, ulStatsAsPercentage;
 *
 *      // 确保写入缓冲区不包含字符串。
 * pcWriteBuffer = 0x00;
 *
 *      // 获取任务数量的快照，以防在此函数执行期间发生变化。
 *      uxArraySize = uxTaskGetNumberOfTasks();
 *
 *      // 为每个任务分配一个 TaskStatus_t 结构体。也可以在编译时静态分配数组。
 *      pxTaskStatusArray = pvPortMalloc( uxArraySize * sizeof( TaskStatus_t ) );
 *
 *      if( pxTaskStatusArray != NULL )
 *      {
 *          // 生成关于每个任务的原始状态信息。
 *          uxArraySize = uxTaskGetSystemState( pxTaskStatusArray, uxArraySize, &ulTotalRunTime );
 *
 *          // 用于百分比计算。
 *          ulTotalRunTime /= 100UL;
 *
 *          // 避免除以零错误。
 *          if( ulTotalRunTime > 0 )
 *          {
 *              // 对 pxTaskStatusArray 数组中每个已填充的位置，
 *              // 将原始数据格式化为人类可读的 ASCII 数据
 *              for( x = 0; x < uxArraySize; x++ )
 *              {
 *                  // 该任务使用了总运行时间的百分之多少？
 *                  // 此计算结果将始终向下取整到最接近的整数。
 *                  // ulTotalRunTimeDiv100 此前已经除以 100。
 *                  ulStatsAsPercentage = pxTaskStatusArray[ x ].ulRunTimeCounter / ulTotalRunTime;
 *
 *                  if( ulStatsAsPercentage > 0UL )
 *                  {
 *                      sprintf( pcWriteBuffer, "%s\t\t%lu\t\t%lu%%\r\n", pxTaskStatusArray[ x ].pcTaskName, pxTaskStatusArray[ x ].ulRunTimeCounter, ulStatsAsPercentage );
 *                  }
 *                  else
 *                  {
 *                      // 如果此处百分比为零，则该任务消耗的运行时间少于总运行时间的 1%。
 *                      sprintf( pcWriteBuffer, "%s\t\t%lu\t\t<1%%\r\n", pxTaskStatusArray[ x ].pcTaskName, pxTaskStatusArray[ x ].ulRunTimeCounter );
 *                  }
 *
 *                  pcWriteBuffer += strlen( ( char * ) pcWriteBuffer );
 *              }
 *          }
 *
 *          // 不再需要该数组，释放其占用的内存。
 *          vPortFree( pxTaskStatusArray );
 *      }
 *  }
 *  @endcode
 */

